pub const STATE_DIRECTORY: &str = "/var/lib/agent-terrier";
pub const USER_ID: u32 = 1000;
pub const GROUP_ID: u32 = 1000;

pub fn typescript() -> String {
    format!(
        "// Generated by agentkeys-protocol; do not edit.\nexport const STATE_DIRECTORY = {STATE_DIRECTORY:?};\nexport const USER_ID = {USER_ID};\nexport const GROUP_ID = {GROUP_ID};\n"
    )
}

#[cfg(test)]
mod tests {
    #[test]
    fn image_layout_matches_the_protocol_owner() {
        assert_eq!(
            super::typescript(),
            include_str!("../../../packages/agentkeys-dsh/src/generated/runtime-layout.ts")
        );
    }
}
